// Simple Asteroid Dodge game
// Targets <canvas id="game"></canvas> in the HTML.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 600;

  // Ship definition
  const ship = {
    x: width / 2,
    y: height / 2,
    size: 20,
    speed: 4,
    dx: 0,
    dy: 0,
    update() {
      this.x = Math.max(this.size, Math.min(width - this.size, this.x + this.dx));
      this.y = Math.max(this.size, Math.min(height - this.size, this.y + this.dy));
    },
    draw() {
      ctx.fillStyle = '#0f0';
      ctx.beginPath();
      ctx.moveTo(this.x, this.y - this.size);
      ctx.lineTo(this.x - this.size, this.y + this.size);
      ctx.lineTo(this.x + this.size, this.y + this.size);
      ctx.closePath();
      ctx.fill();
    },
  };

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });
  function handleInput() {
    ship.dx = 0; ship.dy = 0;
    if (keys.ArrowLeft || keys.a) ship.dx = -ship.speed;
    if (keys.ArrowRight || keys.d) ship.dx = ship.speed;
    if (keys.ArrowUp || keys.w) ship.dy = -ship.speed;
    if (keys.ArrowDown || keys.s) ship.dy = ship.speed;
  }

  // Asteroid definition
  const asteroids = [];
  let asteroidTimer = 0;
  const spawnInterval = 2000; // ms
  function spawnAsteroid() {
    const side = Math.floor(Math.random() * 4);
    let x, y, vx, vy;
    const speed = 1 + Math.random() * 2;
    if (side === 0) { // top
      x = Math.random() * width; y = -20; vx = (width/2 - x) / width * speed; vy = speed;
    } else if (side === 1) { // right
      x = width + 20; y = Math.random() * height; vx = -speed; vy = (height/2 - y) / height * speed;
    } else if (side === 2) { // bottom
      x = Math.random() * width; y = height + 20; vx = (width/2 - x) / width * speed; vy = -speed;
    } else { // left
      x = -20; y = Math.random() * height; vx = speed; vy = (height/2 - y) / height * speed;
    }
    asteroids.push({x, y, vx, vy, r: 15 + Math.random() * 10});
  }

  function updateAsteroids(dt) {
    asteroidTimer += dt;
    if (asteroidTimer > spawnInterval) {
      spawnAsteroid();
      asteroidTimer = 0;
    }
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x += a.vx; a.y += a.vy;
      // Remove if off-screen
      if (a.x < -30 || a.x > width + 30 || a.y < -30 || a.y > height + 30) {
        asteroids.splice(i, 1);
      }
    }
  }

  function drawAsteroids() {
    ctx.fillStyle = '#888';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  function checkCollision() {
    for (const a of asteroids) {
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.r + ship.size) {
        return true;
      }
    }
    return false;
  }

  let lastTime = performance.now();
  let gameOver = false;
  let score = 0;
  function loop(now) {
    const dt = now - lastTime;
    lastTime = now;
    if (!gameOver) {
      handleInput();
      ship.update();
      updateAsteroids(dt);
      if (checkCollision()) {
        gameOver = true;
      }
      score += dt / 1000;
    }
    // Render
    ctx.clearRect(0, 0, width, height);
    drawAsteroids();
    ship.draw();
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score), 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'red';
      ctx.font = '48px sans-serif';
      ctx.fillText('Game Over', width / 2 - 120, height / 2);
    } else {
      requestAnimationFrame(loop);
    }
  }
  requestAnimationFrame(loop);
})();
